import 'package:flutter/material.dart';

/// One word to find. [word] is how it is shown ("BUS STOP", "T-SHIRT");
/// only its letters go into the grid ("BUSSTOP", "TSHIRT").
class WordSearchTarget {
  final String word;
  final String thai;
  final String phonetic;
  final String categoryKey;
  final String imagePath;

  const WordSearchTarget({
    required this.word,
    required this.thai,
    required this.phonetic,
    required this.categoryKey,
    required this.imagePath,
  });

  /// The letters hidden in the grid.
  String get letters => word.replaceAll(RegExp(r'[^A-Z]'), '');

  /// What text-to-speech reads (lower case, so "OWL" isn't spelled out).
  String get spoken => word.toLowerCase();
}


class WordSearchCategoryItem {
  final String key;
  final String titleTh;
  final String titleEn;
  final String cardImagePath;
  final Color cardColor;
  final Color shadowColor;

  const WordSearchCategoryItem({
    required this.key,
    required this.titleTh,
    required this.titleEn,
    required this.cardImagePath,
    required this.cardColor,
    required this.shadowColor,
  });

  List<WordSearchTarget> get words => wordSearchWords[key] ?? const [];

  Set<String> get answers => {for (final w in words) w.word};
}


